import 'package:flutter/foundation.dart';

/// Types of writing intelligence feedback supported in Syaahi Studio.
enum WritingIssueType {
  repeatedWord,
  repeatedPhrase,
  redundancy,
  wordSuggestion,
}

/// A single actionable suggestion generated by the Writing Intelligence engine.
@immutable
class WritingSuggestion {
  final String id;
  final WritingIssueType type;
  final String originalText;
  final String explanation;
  final int startOffset;
  final int endOffset;
  final List<String> alternatives;
  final String? contextSnippet;

  const WritingSuggestion({
    required this.id,
    required this.type,
    required this.originalText,
    required this.explanation,
    required this.startOffset,
    required this.endOffset,
    this.alternatives = const [],
    this.contextSnippet,
  });

  /// Creates a copy with modified attributes.
  WritingSuggestion copyWith({
    String? id,
    WritingIssueType? type,
    String? originalText,
    String? explanation,
    int? startOffset,
    int? endOffset,
    List<String>? alternatives,
    String? contextSnippet,
  }) {
    return WritingSuggestion(
      id: id ?? this.id,
      type: type ?? this.type,
      originalText: originalText ?? this.originalText,
      explanation: explanation ?? this.explanation,
      startOffset: startOffset ?? this.startOffset,
      endOffset: endOffset ?? this.endOffset,
      alternatives: alternatives ?? this.alternatives,
      contextSnippet: contextSnippet ?? this.contextSnippet,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'type': type.name,
      'originalText': originalText,
      'explanation': explanation,
      'startOffset': startOffset,
      'endOffset': endOffset,
      'alternatives': alternatives,
      'contextSnippet': contextSnippet,
    };
  }

  factory WritingSuggestion.fromJson(Map<String, dynamic> json) {
    return WritingSuggestion(
      id: json['id'] as String,
      type: WritingIssueType.values.firstWhere(
        (e) => e.name == json['type'],
        orElse: () => WritingIssueType.repeatedWord,
      ),
      originalText: json['originalText'] as String,
      explanation: json['explanation'] as String,
      startOffset: json['startOffset'] as int,
      endOffset: json['endOffset'] as int,
      alternatives: (json['alternatives'] as List<dynamic>?)
              ?.map((e) => e.toString())
              .toList() ??
          const [],
      contextSnippet: json['contextSnippet'] as String?,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WritingSuggestion &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          type == other.type &&
          originalText == other.originalText &&
          explanation == other.explanation &&
          startOffset == other.startOffset &&
          endOffset == other.endOffset &&
          listEquals(alternatives, other.alternatives) &&
          contextSnippet == other.contextSnippet;

  @override
  int get hashCode =>
      id.hashCode ^
      type.hashCode ^
      originalText.hashCode ^
      explanation.hashCode ^
      startOffset.hashCode ^
      endOffset.hashCode ^
      Object.hashAll(alternatives) ^
      contextSnippet.hashCode;

  @override
  String toString() {
    return 'WritingSuggestion(id: , type: , text: "", alternatives: )';
  }
}

/// Immutable aggregated snapshot of a Writing Intelligence analysis pass.
@immutable
class WritingAnalysisResult {
  final List<WritingSuggestion> suggestions;
  final int totalWords;
  final int uniqueWords;
  final DateTime analyzedAt;

  const WritingAnalysisResult({
    required this.suggestions,
    required this.totalWords,
    required this.uniqueWords,
    required this.analyzedAt,
  });

  factory WritingAnalysisResult.empty() {
    return WritingAnalysisResult(
      suggestions: const [],
      totalWords: 0,
      uniqueWords: 0,
      analyzedAt: DateTime.fromMillisecondsSinceEpoch(0),
    );
  }

  /// Get suggestions filtered by type.
  List<WritingSuggestion> suggestionsOfType(WritingIssueType type) {
    return suggestions.where((s) => s.type == type).toList();
  }

  /// Total count of repeated word suggestions.
  int get repeatedWordCount => suggestionsOfType(WritingIssueType.repeatedWord).length;

  /// Total count of repeated phrase suggestions.
  int get repeatedPhraseCount => suggestionsOfType(WritingIssueType.repeatedPhrase).length;

  /// Total count of redundancy suggestions.
  int get redundancyCount => suggestionsOfType(WritingIssueType.redundancy).length;

  /// Total count of word suggestions.
  int get wordSuggestionCount => suggestionsOfType(WritingIssueType.wordSuggestion).length;

  /// Vocabulary richness ratio (0.0 - 1.0).
  double get vocabularyRichness {
    if (totalWords == 0) return 1.0;
    return uniqueWords / totalWords;
  }

  WritingAnalysisResult copyWith({
    List<WritingSuggestion>? suggestions,
    int? totalWords,
    int? uniqueWords,
    DateTime? analyzedAt,
  }) {
    return WritingAnalysisResult(
      suggestions: suggestions ?? this.suggestions,
      totalWords: totalWords ?? this.totalWords,
      uniqueWords: uniqueWords ?? this.uniqueWords,
      analyzedAt: analyzedAt ?? this.analyzedAt,
    );
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WritingAnalysisResult &&
          runtimeType == other.runtimeType &&
          totalWords == other.totalWords &&
          uniqueWords == other.uniqueWords &&
          analyzedAt == other.analyzedAt &&
          listEquals(suggestions, other.suggestions);

  @override
  int get hashCode =>
      Object.hashAll(suggestions) ^
      totalWords.hashCode ^
      uniqueWords.hashCode ^
      analyzedAt.hashCode;
}
